/// A provider's logo at its design size (16 pt by default).
/// Pass `color` to tint it with the state color (bar / % / logo agree).
struct ProviderLogo: View {
    var kind: ProviderKind
    var size: CGFloat = 16
    var color: Color? = nil
    var body: some View {
        let img = Image(nsImage: kind == .claude ? Marks.claude : Marks.codex)
        if let color {
            img.renderingMode(.template).resizable().interpolation(.high)
                .foregroundStyle(color)
                .frame(width: size, height: size)
        } else {
            img.resizable().interpolation(.high)
                .frame(width: size, height: size)
        }
    }
}
